using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;
using WireMock.RequestBuilders;
using WireMock.ResponseBuilders;
using WireMock.Server;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly WireMockServer provider = WireMockServer.Start();
    private readonly HttpClient client;

    public HttpPaymentGatewayTests() => client = new HttpClient { BaseAddress = new Uri(provider.Url!) };

    private HttpPaymentGateway Sut => new(client);

    private void Provider(int status, string? body = null) =>
        provider.Given(Request.Create().WithPath("/v1/authorizations").UsingPost())
            .RespondWith(Response.Create().WithStatusCode(status).WithHeader("Content-Type", "application/json").WithBody(body ?? ""));

    [Fact]
    public async Task The_request_is_a_json_post_with_reference_amount_and_currency()
    {
        Provider(200, """{"status":"approved"}""");

        await Sut.AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

        var received = Assert.Single(provider.LogEntries).RequestMessage;
        Assert.Equal("POST", received.Method);
        Assert.Equal("/v1/authorizations", received.Path);
        Assert.StartsWith("application/json", received.Headers!["Content-Type"][0]);
        using var json = JsonDocument.Parse(received.Body!);
        Assert.Equal("ORD-7", json.RootElement.GetProperty("reference").GetString());
        Assert.Equal(12.5m, json.RootElement.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", json.RootElement.GetProperty("currency").GetString());
        Assert.Equal(3, json.RootElement.EnumerateObject().Count());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        Provider(200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Sut.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        Provider(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Sut.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        Provider(200, """{"id":"x1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Sut.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task A_refusal_with_402_is_a_declined_outcome()
    {
        Provider(402, """{"error":"insufficient_funds"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Sut.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task An_unknown_status_is_never_treated_as_approved()
    {
        Provider(200, """{"status":"pending"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Sut.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task An_answer_without_a_status_is_never_treated_as_approved()
    {
        Provider(200, """{"decision":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Sut.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_surface_as_errors_instead_of_a_decision(int status)
    {
        Provider(status, """{"error":"boom"}""");

        await Assert.ThrowsAsync<HttpRequestException>(() =>
            Sut.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task A_malformed_body_surfaces_as_an_error()
    {
        Provider(200, "not json");

        await Assert.ThrowsAsync<JsonException>(() =>
            Sut.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    public void Dispose()
    {
        client.Dispose();
        provider.Dispose();
    }
}
